-- Locales: interface translations. The "locales" table itself comes from 001_init.sql
-- (code, name, strings_json, enabled); this adds provenance per locale, seeds four
-- starter translations and the default-locale setting. "en" is built in: its strings
-- always mirror client/src/i18n/en.json and it can be neither edited nor deleted.
CREATE TABLE IF NOT EXISTS locale_meta (
  code        TEXT PRIMARY KEY REFERENCES locales(code) ON DELETE CASCADE,
  builtin     INTEGER NOT NULL DEFAULT 0,
  copied_from TEXT,
  source      TEXT NOT NULL DEFAULT 'seed',
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
);

INSERT OR IGNORE INTO locales (code, name) VALUES ('en', 'English');
INSERT OR IGNORE INTO locale_meta (code, builtin, source) VALUES ('en', 1, 'builtin');

